-- Depots are keyed by their code; drivers work out of one.
CREATE TABLE depots (
    code varchar(10) NOT NULL,
    name varchar(100) NOT NULL,
    city varchar(100),
    PRIMARY KEY (code)
);

CREATE TABLE drivers (
    id bigint NOT NULL GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    depot_code varchar(10) CONSTRAINT drivers_depot_fk REFERENCES depots (code),
    full_name varchar(100) NOT NULL,
    phone varchar(20),
    vehicle varchar(40)
);

CREATE TABLE route_plans (
    id integer NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 1, INCREMENT BY 1),
    depot_code varchar(10) NOT NULL REFERENCES depots (code),
    planned_for date NOT NULL,
    CONSTRAINT route_plans_pk PRIMARY KEY (id)
);
